@implements IAsyncDisposable
@inject IJSRuntime JS

<div @ref="_container">
    @ChildContent
</div>

@code {
    [Parameter] public RenderFragment? ChildContent { get; set; }
    [Parameter] public int TimeoutSeconds { get; set; } = 300;
    [Parameter] public EventCallback OnIdle { get; set; }
    [Parameter] public EventCallback OnActive { get; set; }

    private ElementReference _container;
    private IJSObjectReference? _module;
    private DotNetObjectReference<UserActivityTracker>? _dotNetRef;

    private bool _isIdle;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _dotNetRef = DotNetObjectReference.Create(this);
            _module = await JS.InvokeAsync<IJSObjectReference>(
                "import", "./_content/UserActivityTracker.razor.js");
            await _module.InvokeVoidAsync("initialize", _container, _dotNetRef, TimeoutSeconds * 1000);
        }
    }

    [JSInvokable]
    public async Task OnUserIdle()
    {
        if (!_isIdle)
        {
            _isIdle = true;
            await OnIdle.InvokeAsync();
        }
    }

    [JSInvokable]
    public async Task OnUserActive()
    {
        if (_isIdle)
        {
            _isIdle = false;
            await OnActive.InvokeAsync();
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (_module is not null)
        {
            try
            {
                await _module.InvokeVoidAsync("dispose");
                await _module.DisposeAsync();
            }
            catch (JSDisconnectedException) { }
        }
        _dotNetRef?.Dispose();
    }
}

let timer = null;
let dotNetHelper = null;
let container = null;
let timeoutMs = 300000;
let isIdle = false;

const events = ['mousemove', 'keydown', 'click', 'scroll', 'touchstart'];

function resetTimer() {
    if (isIdle) {
        isIdle = false;
        dotNetHelper.invokeMethodAsync('OnUserActive');
    }
    clearTimeout(timer);
    timer = setTimeout(() => {
        isIdle = true;
        dotNetHelper.invokeMethodAsync('OnUserIdle');
    }, timeoutMs);
}

function handleEvent() {
    resetTimer();
}

export function initialize(element, helper, timeout) {
    container = element;
    dotNetHelper = helper;
    timeoutMs = timeout;
    isIdle = false;

    events.forEach(evt => container.addEventListener(evt, handleEvent, { passive: true }));
    timer = setTimeout(() => {
        isIdle = true;
        dotNetHelper.invokeMethodAsync('OnUserIdle');
    }, timeoutMs);
}

export function dispose() {
    clearTimeout(timer);
    if (container) {
        events.forEach(evt => container.removeEventListener(evt, handleEvent));
    }
    container = null;
    dotNetHelper = null;
    timer = null;
    isIdle = false;
}

